// ==================== UNIVERSAL PAGE NAVIGATION ENGINE ====================
function toggleSub(el) {
    if (!el) return;
    const parent = el.closest('.nav-section') || el.parentElement;
    if (!parent) return;

    const subMenu = parent.querySelector('.sub-menu');
    const chevron = parent.querySelector('.fa-chevron-down, .fa-chevron-up, .fa-chevron-left');

    const isOpen = parent.classList.contains('open') || (subMenu && subMenu.style.display === 'block');

    if (isOpen) {
        parent.classList.remove('open');
        if (subMenu) subMenu.style.display = 'none';
        if (chevron) {
            chevron.classList.remove('fa-chevron-up');
            chevron.classList.add('fa-chevron-down');
        }
    } else {
        parent.classList.add('open');
        if (subMenu) subMenu.style.display = 'block';
        if (chevron) {
            chevron.classList.remove('fa-chevron-down');
            chevron.classList.add('fa-chevron-up');
        }
    }
}
window.toggleSub = toggleSub;

