var currentScheduleTerm = 'الفصل الدراسي الأول';
var currentExamTerm = 'الفصل الدراسي الأول';
var pendingTermTargetPage = null;

function promptTermSelection(targetPageId) {
    pendingTermTargetPage = targetPageId;
    openModal('termModal');
}

function selectTerm(termName) {
    if (pendingTermTargetPage === 'pg-schedule') {
        currentScheduleTerm = termName;
        closeModal('termModal');
        renderSchedule();
    } else if (pendingTermTargetPage === 'pg-exam-schedule') {
        currentExamTerm = termName;
        closeModal('termModal');
        renderExamSchedule();
    } else {
        closeModal('termModal');
    }
}



