window.renderUsersGrid = renderUsersGrid;




function showDataDiffModal(logId) {
    const logs = DB.auditLogsData || [];
    const item = logs.find(l => l.id === logId);
    if (!item) return toast('⚠️ تعذر العثور على سجل العملية', 1);

    const logIdEl = document.getElementById('diffLogId');
    const tsEl = document.getElementById('diffTimestamp');
    const oldValEl = document.getElementById('diffOldValue');
    const newValEl = document.getElementById('diffNewValue');

    if (logIdEl) logIdEl.textContent = 'كود العملية: ' + item.id + ' | ' + item.module;
    if (tsEl) tsEl.textContent = 'التوقيت: ' + item.timestamp + ' | IP: ' + item.ipClient;
    if (oldValEl) oldValEl.textContent = item.oldValue || '{}';
    if (newValEl) newValEl.textContent = item.newValue || '{}';

    document.getElementById('diffModal')?.classList.add('active');
}
window.showDataDiffModal = showDataDiffModal;

function exportAuditLogs(format) {
    if (format === 'pdf') {
        toast('📄 جاري توليد مستند سجل الحركات والمحفوظات المشفر (PDF)...');
        setTimeout(() => { window.print(); }, 600);
    } else {
        toast('📊 جاري تصدير سجل المحفوظات الأمنية بصيغة CSV...');
        setTimeout(() => { toast('✅ تم تحميل ملف السجل المشفر بنجاح'); }, 800);
    }
}
window.exportAuditLogs = exportAuditLogs;



function renderAuditGrid() {
    const tb = document.getElementById('tbl-audit-logs-grid');
    if (!tb) return;

    const query = (document.getElementById('searchAudit')?.value || (document.getElementById('auditSearchInput') || document.getElementById('searchAudit'))?.value || '').toLowerCase();

    const modFilter = document.getElementById('auditModuleFilter')?.value || 'all';
    const actionFilter = document.getElementById('auditActionFilter')?.value || 'all';
    const sevFilter = document.getElementById('auditSeverityFilter')?.value || 'all';

    const logs = DB.auditLogsData || DB.audit || [
        {
            id: 'LOG-2026-0811-9921',
            userRole: 'أ. خالد محمود العنسي (مسؤول الكنترول)',
            timestamp: '2026-08-11 10:22:15',
            module: 'نظام الكنترول والامتحانات',
            actionType: 'UPDATE',
            targetEntity: 'Student_Grades (ID: 1042)',
            oldValue: JSON.stringify({ grade: 85, status: "Pending", subject: "الرياضيات" }, null, 2),
            newValue: JSON.stringify({ grade: 95, status: "Approved", subject: "الرياضيات" }, null, 2),
            ipClient: '192.168.1.45 (Windows 11 / Chrome)',
            severity: 'عالي الخطورة'
        },
        {
            id: 'LOG-2026-0811-9850',
            userRole: 'م. حسام الدين (مدير النظام)',
            timestamp: '2026-08-11 09:45:10',
            module: 'الشؤون المالية',
            actionType: 'DELETE',
            targetEntity: 'Voucher_Receipt (ID: 554)',
            oldValue: JSON.stringify({ voucherNo: "RV-2026-0045", amount: 500, payer: "علي السالمي" }, null, 2),
            newValue: JSON.stringify({ status: "DELETED", reason: "إلغاء السند بطلب المحاسب" }, null, 2),
            ipClient: '192.168.1.10 (macOS / Safari)',
            severity: 'عالي الخطورة'
        },
        {
            id: 'LOG-2026-0811-9720',
            userRole: 'أ. إبراهيم العنسي (مسؤول المعامل)',
            timestamp: '2026-08-11 08:30:00',
            module: 'المخازن والمشتريات',
            actionType: 'INSERT',
            targetEntity: 'Goods_Issue_Note (GIN-2026-0214)',
            oldValue: JSON.stringify({}, null, 2),
            newValue: JSON.stringify({ ginNo: "GIN-2026-0214", item: "طابعة HP Laser", qty: 2 }, null, 2),
            ipClient: '192.168.1.88 (Windows 10 / Firefox)',
            severity: 'عادي'
        },
        {
            id: 'LOG-2026-0811-9500',
            userRole: 'أ. سارة أحمد (مسؤولة التسجيل)',
            timestamp: '2026-08-11 07:50:12',
            module: 'شؤون الطلاب',
            actionType: 'LOGIN',
            targetEntity: 'UserSession (USR-2026-0104)',
            oldValue: JSON.stringify({ session: "Inactive" }, null, 2),
            newValue: JSON.stringify({ session: "Active", ip: "192.168.1.12" }, null, 2),
            ipClient: '192.168.1.12 (Windows 11 / Chrome)',
            severity: 'عادي'
        }
    ];

    const filtered = logs.filter(l => {
        const matchQ = !query || [l.id, l.userRole, l.module, l.targetEntity, l.ipClient].some(val => (val || '').toLowerCase().includes(query));
        const matchM = modFilter === 'all' || l.module === modFilter;
        const matchA = actionFilter === 'all' || l.actionType === actionFilter;
        const matchS = sevFilter === 'all' || l.severity === sevFilter;
        return matchQ && matchM && matchA && matchS;
    });

    const totEl = (document.getElementById('auditTotalCount') || document.getElementById('auditTotalLogs'));
    const hrEl = document.getElementById('auditHighRiskCount');
    if (totEl) totEl.textContent = logs.length + ' حركـة';
    if (hrEl) hrEl.textContent = logs.filter(x => x.severity === 'عالي الخطورة').length + ' حركات';

    tb.innerHTML = filtered.map(l => {
        const isHigh = l.severity === 'عالي الخطورة';
        const actionColors = {
            'UPDATE': { bg: 'rgba(245,158,11,0.15)', color: '#f59e0b', label: 'تعديل (UPDATE)' },
            'DELETE': { bg: 'rgba(239,68,68,0.15)', color: '#ef4444', label: 'حذف (DELETE)' },
            'INSERT': { bg: 'rgba(16,185,129,0.15)', color: '#10b981', label: 'إضافة (INSERT)' },
            'LOGIN': { bg: 'rgba(59,130,246,0.15)', color: '#3b82f6', label: 'دخول (LOGIN)' }
        };
        const actInfo = actionColors[l.actionType] || { bg: 'rgba(107,114,128,0.15)', color: '#9ca3af', label: l.actionType || 'حركة' };
        const oldSnippet = l.oldValue ? (typeof l.oldValue === 'object' ? JSON.stringify(l.oldValue) : String(l.oldValue)).slice(0, 35) : '—';
        const newSnippet = l.newValue ? (typeof l.newValue === 'object' ? JSON.stringify(l.newValue) : String(l.newValue)).slice(0, 35) : '—';

        return `
            <tr style="${isHigh ? 'background:rgba(239,68,68,0.03);' : ''}">
                <td style="font-weight:700;color:#60a5fa;font-family:monospace;">${l.id || 'LOG-101'}</td>
                <td style="font-weight:700;">${l.userRole || l.user || 'مدير النظام'}</td>
                <td style="font-size:0.8rem;color:var(--muted);">${l.timestamp || l.time || 'الآن'}</td>
                <td style="font-weight:600;">${l.module || l.action || 'عام'}</td>
                <td><span style="padding:3px 8px;border-radius:6px;font-size:0.75rem;font-weight:700;background:${actInfo.bg};color:${actInfo.color};">${actInfo.label}</span></td>
                <td style="font-size:0.83rem;color:#c084fc;font-family:monospace;">${l.targetEntity || l.details || 'عام'}</td>
                <td style="font-size:0.75rem;color:var(--muted);max-width:140px;overflow:hidden;text-overflow:ellipsis;">${oldSnippet}</td>
                <td style="font-size:0.75rem;color:#34d399;max-width:140px;overflow:hidden;text-overflow:ellipsis;">${newSnippet}</td>
                <td style="font-size:0.78rem;">${l.ipClient || '192.168.1.1'}</td>
                <td>
                    <span style="padding:3px 8px;border-radius:6px;font-size:0.75rem;font-weight:700;background:${isHigh ? 'rgba(239,68,68,0.2)' : 'rgba(16,185,129,0.15)'};color:${isHigh ? '#ef4444' : '#10b981'};">
                        ${isHigh ? '🔥 عالي الخطورة' : '🟢 عادي'}
                    </span>
                </td>
            </tr>
        `;
    }).join('');
}
window.renderAuditGrid = renderAuditGrid;
function renderAudit() { renderAuditGrid(); }
window.renderAudit = renderAudit;

function renderSystemSettingsGrid() {
    const tb = document.getElementById('tbl-system-settings-grid');
    if (!tb) return;

    const query = (document.getElementById('searchSystemSettings')?.value || (document.getElementById('searchSettings') || document.getElementById('searchSystemSettings'))?.value || '').toLowerCase();

    const settings = DB.systemSettingsData || [
        { keyId: 'SYS_UI_PRIMARY_COLOR', settingName: 'اللون الرئيسي للواجهة', category: 'المظهر والألوان', val: '#1E40AF (أزرق ملكي)', controlType: 'Color Picker', lastBy: 'أ. خالد العنسي', lastTs: '2026-08-14 - 10:00 AM' },
        { keyId: 'SYS_UI_THEME_MODE', settingName: 'مظهر النظام (النمط)', category: 'المظهر والألوان', val: 'الوضع الداكن (Dark)', controlType: 'Segmented Control', lastBy: 'أ. خالد العنسي', lastTs: '2026-08-14 - 09:30 AM' },
        { keyId: 'SYS_SESSION_TIMEOUT_MINS', settingName: 'مدة إغلاق الجلسة التلقائي', category: 'الأمان والحماية', val: '15 دقيقة', controlType: 'Select Box', lastBy: 'أ. خالد العنسي', lastTs: '2026-08-12 - 09:15 PM' },
        { keyId: 'SYS_MFA_ENFORCED', settingName: 'تفعيل التحقق الثنائي (MFA)', category: 'الأمان والحماية', val: 'مفعل (True)', controlType: 'Toggle Switch', lastBy: 'د. سارة أحمد', lastTs: '2026-08-10 - 02:20 PM' },
        { keyId: 'SYS_AUTO_BACKUP_CRON', settingName: 'جدول النسخ الاحتياطي', category: 'النسخ والصيانة', val: 'يومياً (02:00 AM)', controlType: 'Cron Picker', lastBy: 'م. علي باجمال', lastTs: '2026-08-01 - 11:00 AM' },
        { keyId: 'SYS_MAINTENANCE_MODE', settingName: 'وضع الصيانة المؤقت', category: 'النسخ والصيانة', val: 'غير مفعل (System Live)', controlType: 'Toggle Switch', lastBy: 'أ. خالد العنسي', lastTs: '2026-08-13 - 04:45 PM' }
    ];

    const filtered = settings.filter(s => {
        const name = s.settingName || s.nameArEn || '';
        const key = s.keyId || '';
        const cat = s.category || s.scope || '';
        const val = s.val || '';
        return !query || [key, name, cat, val].some(v => (v || '').toLowerCase().includes(query));
    });

    tb.innerHTML = filtered.map(s => {
        const name = s.settingName || s.nameArEn || 'إعداد سيادي';
        const key = s.keyId || 'SYS_KEY';
        const cat = s.category || s.scope || 'عام (General)';
        const val = s.val || 'مفعل';
        const ctrl = s.controlType || s.type || 'Segmented Control';
        const by = s.lastBy || 'أ. خالد العنسي';
        const ts = s.lastTs || '2026-08-14 - 10:00 AM';

        return `
            <tr>
                <td style="font-weight:700;color:#e2e8f0;">${name}</td>
                <td><span style="padding:3px 8px;border-radius:6px;font-size:0.75rem;background:rgba(59,130,246,0.15);color:#60a5fa;font-weight:700;">${cat}</span></td>
                <td style="font-size:0.8rem;color:#c084fc;font-family:monospace;font-weight:700;">${key}</td>
                <td style="font-weight:700;color:#10b981;">${val}</td>
                <td><span style="padding:3px 8px;border-radius:6px;font-size:0.75rem;background:rgba(245,158,11,0.15);color:#fbbf24;font-weight:700;">${ctrl}</span></td>
                <td style="font-size:0.8rem;">${by}</td>
                <td style="font-size:0.78rem;color:var(--muted);">${ts}</td>
            </tr>
        `;
    }).join('');
}
