// ==================== A. ACADEMIC CALENDAR ====================
// window.currentCalViewMode

function switchCalView(mode, btnEl) {
    currentCalViewMode = mode;
    if (btnEl) {
        btnEl.parentElement.querySelectorAll('.tab-btn, button').forEach(b => b.classList.remove('active'));
        btnEl.classList.add('active');
    }
    toast('📅 تم التبديل لعرض التقويم: ' + (mode === 'week' ? 'الأساسي الأسبوعي 🗓️' : (mode === 'day' ? 'اليومي ☀️' : (mode === 'agenda' ? 'جدول الأعمال 📋' : 'الشهري 🗓️'))));
    renderAcademicCalendar();
}
window.switchCalView = switchCalView;

/* ===== 📅 Responsive Scaled Academic Calendar Engine ===== */
if (typeof window.selectedCalMonthYear === 'undefined') window.selectedCalMonthYear = '2026-08';
if (typeof window.currentCalViewMode === 'undefined') window.currentCalViewMode = 'month';

function switchCalView(mode, btn) {
    currentCalViewMode = mode;
    document.querySelectorAll('#pg-academic-calendar .tab-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderAcademicCalendar();
}
window.switchCalView = switchCalView;

function jumpToSelectedCalendarDate(val) {
    if (!val) return;
    selectedCalMonthYear = val; // format "2026-08"
    const label = document.getElementById('selectedCalMonthLabel');
    if (label) {
        const parts = val.split('-');
        const year = parts[0];
        const month = parts[1];
        const monthNames = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
        const mIdx = parseInt(month) - 1;
        label.innerHTML = `📅 المعروض حالياً: <strong>${monthNames[mIdx] || month} ${year}</strong>`;
    }
    renderAcademicCalendar();
    toast(`📅 تم التوجيه لعرض تقويم شهر: ${val}`);
}
window.jumpToSelectedCalendarDate = jumpToSelectedCalendarDate;

function renderAcademicCalendar() {
    const container = document.getElementById('calViewContainer');
    if (!container) return;

    if (!DB.calendarEvents || DB.calendarEvents.length === 0) {
        DB.calendarEvents = [
            { id: 1, title: 'امتحانات منتصف الفصل الدراسي الأول', category: 'امتحانات', startDate: '2026-08-15', endDate: '2026-08-25', dayStatus: 'يوم دراسي فعلي', audience: 'الطلاب والمعلمين', location: 'القاعة الكبرى', color: '#3b82f6', publishStatus: 'منشور 🟢' },
            { id: 2, title: 'إجازة ثورة 26 سبتمبر الوطنية', category: 'إجازة رسمية', startDate: '2026-09-26', endDate: '2026-09-26', dayStatus: 'تعطيل الدراسة', audience: 'الجميع', location: 'جميع الفروع', color: '#ef4444', publishStatus: 'منشور 🟢' },
            { id: 3, title: 'المسابقة الثقافية والابتكارات الطلابية', category: 'نشاط مدرسي', startDate: '2026-08-28', endDate: '2026-08-28', dayStatus: 'نصف يوم دراسي', audience: 'الطلاب', location: 'مسرح المدرسة', color: '#10b981', publishStatus: 'منشور 🟢' },
            { id: 4, title: 'اجتماع الجمعية العمومية لأولياء الأمور', category: 'اجتماع', startDate: '2026-08-30', endDate: '2026-08-30', dayStatus: 'يوم دراسي فعلي', audience: 'أولياء الأمور', location: 'القاعة الكبرى', color: '#f59e0b', publishStatus: 'منشور 🟢' }
        ];
    }

    const events = DB.calendarEvents;
    const stageFilter = document.getElementById('calFilterStage')?.value || 'all';
    const audienceFilter = document.getElementById('calFilterAudience')?.value || 'all';

    const filtered = events.filter(e => {
        const matchS = stageFilter === 'all' || (e.audience || '').includes(stageFilter);
        const matchA = audienceFilter === 'all' || (e.audience || '').includes(audienceFilter);
        return matchS && matchA;
    });

    if (currentCalViewMode === 'agenda') {
        container.innerHTML = `
            <div class="table-wrapper">
                <table>
                    <thead>
                        <tr>
                            <th>اسم الفعالية / الحدث</th>
                            <th>التصنيف ولون الحدث</th>
                            <th>تاريخ البداية</th>
                            <th>تاريخ النهاية</th>
                            <th>حالة اليوم</th>
                            <th>الفئة المستهدفة</th>
                            <th>الموقع</th>
                            <th>حالة النشر</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${filtered.map(e => `
                            <tr onclick="openForm('academic-calendar', ${JSON.stringify(e).replace(/"/g, '&quot;')})" style="cursor:pointer;">
                                <td style="font-weight:700;color:${(e.color||'#3b82f6').split(' ')[0]};"><i class="fa-solid fa-circle" style="font-size:0.6rem;margin-left:6px;"></i> ${e.title}</td>
                                <td><span style="padding:4px 10px;border-radius:6px;font-size:0.75rem;background:${(e.color||'#3b82f6').split(' ')[0]}22;color:${(e.color||'#3b82f6').split(' ')[0]};font-weight:700;border:1px solid ${(e.color||'#3b82f6').split(' ')[0]}55;">${e.category}</span></td>
                                <td>${e.startDate}</td>
                                <td>${e.endDate}</td>
                                <td>${e.dayStatus}</td>
                                <td>${e.audience}</td>
                                <td>${e.location}</td>
                                <td><span style="padding:2px 6px;border-radius:4px;font-size:0.75rem;background:rgba(16,185,129,0.15);color:#10b981;">${e.publishStatus || 'منشور 🟢'}</span></td>
                            </tr>
                        `).join('')}
                    </tbody>
                </table>
            </div>
        `;
    } else if (currentCalViewMode === 'day') {
        const hours = ['08:00 AM', '09:00 AM', '10:00 AM', '11:00 AM', '12:00 PM', '01:00 PM', '02:00 PM'];
        container.innerHTML = `
            <div style="background:var(--bg-elevated);border:1px solid var(--border-color);border-radius:10px;padding:15px;">
                <h4 style="color:#60a5fa;margin-top:0;display:flex;align-items:center;gap:8px;"><i class="fa-solid fa-calendar-day"></i> جدول الفعاليات والأحداث اليومية التفصيلية</h4>
                <div style="display:flex;flex-direction:column;gap:8px;">
                    ${hours.map((h, i) => {
                        const ev = filtered[i % filtered.length];
                        const col = (ev.color || '#3b82f6').split(' ')[0];
                        return `
                            <div style="display:grid;grid-template-columns:100px 1fr;gap:12px;align-items:center;background:var(--bg-card);padding:10px;border-radius:8px;border:1px solid var(--border-color);">
                                <span style="font-weight:700;color:var(--muted);">${h}</span>
                                <div style="padding:8px 12px;border-radius:6px;background:${col}25;border-right:4px solid ${col};color:${col};font-weight:700;">
                                    ${ev.title} (${ev.category}) - ${ev.audience}
                                </div>
                            </div>
                        `;
                    }).join('')}
                </div>
            </div>
        `;
    } else if (currentCalViewMode === 'week') {
        const days = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
        container.innerHTML = `
            <div class="table-wrapper">
                <div style="display:grid;grid-template-columns:repeat(7, 1fr);gap:6px;width:100%;box-sizing:border-box;">
                    ${days.map(d => `<div style="text-align:center;font-weight:700;padding:8px;background:rgba(59,130,246,0.15);color:#93c5fd;border-radius:6px;font-size:0.85rem;">${d}</div>`).join('')}
                    ${days.map((d, i) => {
                        const eventThisDay = filtered[i % filtered.length];
                        const col = eventThisDay ? (eventThisDay.color || '#3b82f6').split(' ')[0] : '#3b82f6';
                        return `
                            <div onclick="openForm('academic-calendar')" style="min-height:100px;background:var(--bg-card);border:1px solid var(--border-color);border-radius:8px;padding:6px;cursor:pointer;box-sizing:border-box;">
                                <span style="font-size:0.8rem;font-weight:800;color:#60a5fa;">يوم ${d}</span>
                                ${eventThisDay ? `
                                    <div style="margin-top:6px;padding:4px 6px;border-radius:6px;font-size:0.72rem;font-weight:700;background:${col}33;color:${col};border-right:3px solid ${col};">
                                        📌 ${eventThisDay.title}
                                    </div>
                                ` : ''}
                            </div>
                        `;
                    }).join('')}
                </div>
            </div>
        `;
    } else {
        // Month Grid View - Scaled & Fitted Inside Container (تقليص الحجم ليتناسب 100% مع الإطار)
        const days = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
        container.innerHTML = `
            <div class="table-wrapper" style="border:none;padding:0;margin:0;">
                <div style="display:grid;grid-template-columns:repeat(7, 1fr);gap:5px;width:100%;max-width:100%;box-sizing:border-box;">
                    ${days.map(d => `<div style="text-align:center;font-weight:700;padding:6px 2px;background:rgba(59,130,246,0.15);color:#93c5fd;border-radius:6px;font-size:0.78rem;">${d}</div>`).join('')}
                    ${Array(35).fill(0).map((_, i) => {
                        const dayNum = (i % 31) + 1;
                        const eventThisDay = (i % 7 === 2 || i % 9 === 0) ? filtered[i % filtered.length] : null;
                        const col = eventThisDay ? (eventThisDay.color || '#3b82f6').split(' ')[0] : '#3b82f6';
                        return `
                            <div onclick="openForm('academic-calendar')" style="min-height:60px;max-height:80px;background:var(--bg-card);border:1px solid var(--border-color);border-radius:6px;padding:4px;cursor:pointer;position:relative;box-sizing:border-box;overflow:hidden;" title="انقر لإضافة/تعديل حدث في هذا اليوم">
                                <span style="font-size:0.75rem;font-weight:700;color:var(--muted);display:block;margin-bottom:2px;">${dayNum}</span>
                                ${eventThisDay ? `
                                    <div style="padding:3px 5px;border-radius:4px;font-size:0.68rem;font-weight:700;background:${col}28;color:${col};border-right:3px solid ${col};white-space:nowrap;text-overflow:ellipsis;overflow:hidden;">
                                        ${eventThisDay.title}
                                    </div>
                                ` : ''}
                            </div>
                        `;
                    }).join('')}
                </div>
            </div>
        `;
    }
}
window.renderAcademicCalendar = renderAcademicCalendar;

