let activeTimetableViewMode = 'class';

function switchTimetableView(mode) {
    activeTimetableViewMode = mode;
    const btnClass = document.getElementById('btnTtViewClass');
    const btnTeacher = document.getElementById('btnTtViewTeacher');
    const btnRoom = document.getElementById('btnTtViewRoom');
    
    if (btnClass) { btnClass.style.background = mode === 'class' ? '#3b82f6' : 'transparent'; btnClass.style.color = mode === 'class' ? '#fff' : 'var(--text-main)'; }
    if (btnTeacher) { btnTeacher.style.background = mode === 'teacher' ? '#3b82f6' : 'transparent'; btnTeacher.style.color = mode === 'teacher' ? '#fff' : 'var(--text-main)'; }
    if (btnRoom) { btnRoom.style.background = mode === 'room' ? '#3b82f6' : 'transparent'; btnRoom.style.color = mode === 'room' ? '#fff' : 'var(--text-main)'; }
    
    renderInteractiveTimetable();
    const modeNames = { 'class': 'جدول الصف والشعبة', 'teacher': 'جدول المعلم الشخصي والنصاب', 'room': 'جدول القاعات والمختبرات' };
    toast(`🔄 تم التبديل إلى عرض: ${modeNames[mode] || mode}`);
}
window.switchTimetableView = switchTimetableView;

function renderInteractiveTimetable() {
    const matrix = document.getElementById('interactiveTimetableMatrix');
    const pool = document.getElementById('ttUnassignedPool');
    
    renderTimetableGridTable();

    if (!matrix) return;

    const days = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء'];
    const periods = [
        'الحصة الأولى<br><small style="font-weight:normal;opacity:0.8;">08:00 - 08:45</small>',
        'الحصة الثانية<br><small style="font-weight:normal;opacity:0.8;">08:50 - 09:35</small>',
        'الحصة الثالثة<br><small style="font-weight:normal;opacity:0.8;">09:40 - 10:25</small>',
        'الحصة الرابعة<br><small style="font-weight:normal;opacity:0.8;">10:40 - 11:25</small>',
        'الحصة الخامسة<br><small style="font-weight:normal;opacity:0.8;">11:30 - 12:15</small>',
        'الحصة السادسة<br><small style="font-weight:normal;opacity:0.8;">12:20 - 01:05</small>',
        'الحصة السابعة<br><small style="font-weight:normal;opacity:0.8;">01:10 - 01:55</small>'
    ];

    // Force 8 columns grid template (1 Day column + 7 Period columns)
    matrix.style.display = 'grid';
    matrix.style.gridTemplateColumns = '130px repeat(7, 1fr)';
    matrix.style.gap = '6px';
    matrix.style.width = '100%';
    matrix.style.boxSizing = 'border-box';
    matrix.style.minWidth = '950px';

    // 1. Top Header Row: [اليوم / الحصة] + [الحصة الأولى ... الحصة السابعة]
    let h = `
        <div class="timetable-cell header" style="text-align:center;font-weight:800;background:var(--bg-elevated);color:var(--text-main);padding:10px 4px;border-radius:6px;font-size:0.85rem;border:1px solid var(--border-color);display:flex;align-items:center;justify-content:center;gap:6px;">
            <i class="fa-solid fa-calendar-week" style="color:#60a5fa;"></i> اليوم / الحصة
        </div>
        ${periods.map(p => `
            <div class="timetable-cell header" style="text-align:center;font-weight:800;background:rgba(59,130,246,0.18);color:#93c5fd;padding:8px 4px;border-radius:6px;font-size:0.82rem;border:1px solid rgba(59,130,246,0.3);display:flex;flex-direction:column;align-items:center;justify-content:center;">
                ${p}
            </div>
        `).join('')}
    `;

    // 2. Vertical Rows: Days (السبت، الأحد، الاثنين، الثلاثاء، الأربعاء)
    days.forEach(d => {
        // Day Header in Column 1
        h += `
            <div class="timetable-cell day-col" style="display:flex;align-items:center;justify-content:center;font-weight:800;background:var(--bg-elevated);color:#60a5fa;padding:10px 6px;border-radius:6px;font-size:0.85rem;border:1px solid var(--border-color);">
                🗓️ ${d}
            </div>
        `;

        // 7 Period Cells for Day d
        periods.forEach((_, pIdx) => {
            const periodNo = pIdx + 1;
            const slotMatch = (DB.timetableGridData || []).find(t => t.dayPeriod && t.dayPeriod.includes(d) && t.dayPeriod.includes('الحصة ' + periodNo));
            
            if (slotMatch) {
                const colorHex = slotMatch.subject.includes('برمجة') || slotMatch.subject.includes('هياكل') ? '#8b5cf6' : (slotMatch.subject.includes('بدنية') ? '#10b981' : '#3b82f6');
                h += `
                    <div class="timetable-cell filled" onclick="openTimetableAssign('${slotMatch.slotCode}')" style="min-height:75px;background:${colorHex}22;border:1px solid ${colorHex}55;border-right:4px solid ${colorHex};cursor:pointer;padding:6px;border-radius:6px;box-sizing:border-box;" title="${slotMatch.slotCode}">
                        <strong style="color:${colorHex};font-size:0.8rem;display:block;margin-bottom:2px;">${slotMatch.subject}</strong>
                        <span style="font-size:0.72rem;color:var(--muted);display:block;">👤 ${slotMatch.teacher}</span>
                        <span style="font-size:0.7rem;color:var(--text-main);display:block;margin-top:2px;">🏫 ${slotMatch.room}</span>
                    </div>
                `;
            } else {
                h += `
                    <div class="timetable-cell empty" onclick="openTimetableAssign(null, '${d}', ${periodNo})" style="min-height:75px;background:var(--bg-card);border:1px dashed var(--border-color);border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:0.75rem;box-sizing:border-box;" title="انقر لإسناد حصة يوم ${d} - الحصة ${periodNo}">
                        + إسناد
                    </div>
                `;
            }
        });
    });

    matrix.innerHTML = h;

    if (pool) {
        pool.innerHTML = [
            { name: 'الكيمياء العامة (عملي)', required: '2 حصص أسبوعياً', teacher: 'أ. إبراهيم علي', room: 'مختبر الكيمياء' },
            { name: 'الرياضيات التطبيقية', required: '3 حصص أسبوعياً', teacher: 'أ. محمد علي', room: 'قاعة 102' },
            { name: 'النشاط العلمي والابتكار', required: '1 حصة أسبوعياً', teacher: 'أ. سارة أحمد', room: 'معمل الابتكار' }
        ].map(p => `
            <div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:8px;padding:8px;font-size:0.8rem;">
                <strong style="color:#60a5fa;display:block;">${p.name}</strong>
                <span style="color:var(--muted);">${p.required} | ${p.teacher}</span>
            </div>
        `).join('');
    }
}
window.renderInteractiveTimetable = renderInteractiveTimetable;



