/* ===== Safe Render Helper for Vouchers ===== */
function renderVouchers() {
    const el = document.getElementById('tbl-vouchers') || document.getElementById('tbl-voucher_receipt');
    if (!el) return;
    const data = DB.vouchers || [];
    el.innerHTML = data.map((v, i) => `
        <tr>
            <td>${i + 1}</td>
            <td><code style="color:#60a5fa;font-weight:700;">${v.id}</code></td>
            <td>📅 ${v.date}</td>
            <td><span class="badge ${v.type==='قبض'?'badge-success':'badge-danger'}">${v.type}</span></td>
            <td style="font-weight:700;color:#34d399;">${v.amount}</td>
            <td>👤 ${v.payer || v.payee || v.account}</td>
            <td><span class="badge badge-info">${v.paymentMethod || 'نقداً (Cash)'}</span></td>
            <td><code>${v.transactionRef || 'TRX-9988234'}</code></td>
            <td>${v.costCenter || 'إيرادات الرسوم'}</td>
            <td>🏦 ${v.account || 'الصندوق الرئيسي'}</td>
            <td>${v.attachmentDoc ? '📷 مرفق' : 'غير مرفق'}</td>
            <td>${v.notes}</td>
            <td><span class="badge badge-success">${v.status || 'معتمد 🟢'}</span></td>
            <td>
                <div class="act">
                    <button class="btn-edit" onclick="openForm('voucher_${v.type==='صرف'?'payment':'receipt'}', ${JSON.stringify(v).replace(/"/g, '&quot;')})"><i class="fa-solid fa-pen"></i></button>
                    <button class="btn-delete" onclick="toast('🗑️ حذف السند')"><i class="fa-solid fa-trash"></i></button>
                </div>
            </td>
        </tr>
    `).join('') || '<tr><td colspan="14" style="text-align:center;color:var(--muted);">لا توجد سندات مسجلة</td></tr>';
}
window.renderVouchers = renderVouchers;


/* ===== Master Global Table Hydration Launcher (ReferenceError Immune) ===== */
/* ===== Master Global Table Hydration Launcher (100% ReferenceError Immune) ===== */
function hydrateAndMountAllGrids() {
    if (typeof ensureAllDataPresent === 'function') ensureAllDataPresent();

    const rendererNames = [
        'renderAttendance', 'renderScheduleList', 'renderSchoolsGrid', 'renderParentsGrid',
        'renderViolationsCatalogGrid', 'renderGradeProgressionGrid', 'renderGradeTypesGrid',
        'renderGradeRatingsGrid', 'renderExamScheduleGrid', 'renderDashboard', 'renderUsersGrid',
        'renderStudentRegister', 'renderStudents', 'renderEmployees', 'renderSubjects',
        'renderVouchers', 'renderCurrenciesGrid', 'renderCashboxInventoryGrid', 'renderClosingsGrid',
        'renderBanksGrid', 'renderDemandLettersGrid', 'renderSystemSettingsGrid', 'renderWhatsappSendGrid',
        'renderWhatsappSettingsGrid', 'renderAuditGrid', 'renderAlertsGrid', 'renderArchiveGrid',
        'renderPostingGrid', 'renderSchoolInfo', 'renderPayrollMasterGrid', 'renderEmpAttendanceGrid',
        'renderInteractiveTimetable', 'renderInventoryItemsGrid', 'renderActivitiesGrid',
        'renderTransportRoutesGrid', 'renderClassroomsGrid', 'renderEmpContractsGrid',
        'renderEmpAdvancesGrid', 'renderEmpNoticesGrid', 'renderItemCategoriesGrid',
        'renderSupplyOrdersGrid', 'renderSuppliersGrid', 'renderShortcutsGrid', 'renderFaqGrid',
        'renderDictionaryGrid', 'renderPersonalInfoGrid', 'renderAcademicYearsGrid',
        'renderStagesGrid', 'renderSectionsGrid', 'renderSubjectDistGrid', 'renderClassTimesGrid',
        'renderRequiredDocsGrid', 'renderFeeCategoriesGrid', 'renderDiscountCategoriesGrid',
        'renderInstallmentPlansGrid', 'renderGradeFeesGrid'
    ];

    rendererNames.forEach(fnName => {
        try {
            if (typeof window[fnName] === 'function') {
                window[fnName]();
            }
        } catch(e) {
            console.warn('Hydration grid warning for ' + fnName + ':', e);
        }
    });
}
window.hydrateAndMountAllGrids = hydrateAndMountAllGrids;


// Auto-Mount on Script Load, DOMContentLoaded, and Window Load
hydrateAndMountAllGrids();

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hydrateAndMountAllGrids);
} else {
    hydrateAndMountAllGrids();
}
window.addEventListener('load', hydrateAndMountAllGrids);









