function toggleAllUserPermissions(allow) {
    document.querySelectorAll('.user-page-perm-input').forEach(sel => {
        sel.value = allow ? 'allow' : 'deny';
        sel.style.color = allow ? '#10b981' : '#ef4444';
    });
    toast(allow ? '🟢 تم منح الوصول لجميع شاشات النظام' : '🔴 تم حظر جميع شاشات النظام لهذا الحساب');
}
window.toggleAllUserPermissions = toggleAllUserPermissions;

function saveForm(type) {
    type = type || window.currentEditingType || 'student';
    const collKey = getCollectionKey(type);
    if (!DB[collKey]) DB[collKey] = [];

    const editId = window.currentEditingId;
    const fields = getFormFields(type);

    const newRec = {};
    for (const f of fields) {
        const el = document.getElementById(f.id);
        if (el) {
            const val = el.value ? String(el.value).trim() : '';
            // Required field validation check
            if (f.required && !val) {
                el.classList.add('is-invalid');
                el.style.border = '2px solid #ef4444';
                el.style.boxShadow = '0 0 0 3px rgba(239, 68, 68, 0.25)';
                el.focus();
                const fieldLabel = (f.label || f.key || '').replace('*', '').trim() || 'هذا الحقل';
                toast(`⚠️ يرجى تعبئة الحقل الإلزامي: (${fieldLabel})`, 1);
                return false;
            } else {
                el.classList.remove('is-invalid');
                el.style.border = '';
                el.style.boxShadow = '';
            }
            newRec[f.key] = val;
        }
    }

    if (type === 'users') {
        newRec.pagePermissions = {};
        let allowed = 0, total = 0;
        document.querySelectorAll('.user-page-perm-input').forEach(sel => {
            total++;
            const pId = sel.dataset.pageId;
            const isAllow = sel.value === 'allow';
            newRec.pagePermissions[pId] = isAllow;
            if (isAllow) allowed++;
        });
        newRec.allowedPagesCount = `${allowed} / ${total} واجهة مسموحة 🟢`;
    }

    if (editId) {
        let item = DB[collKey].find(x =>
            x.id == editId || x.keyId == editId || x.isoCode == editId ||
            x.provider == editId || x.name == editId || x.code == editId
        );
        if (item) {
            Object.assign(item, newRec);
            toast('✅ تم تحديث بيانات السجل بنجاح!');
        } else {
            toast('⚠️ لم يتم العثور على السجل لتحديثه', 1);
        }
    } else {
        const prefix = {
            'student':'STD','employee':'EMP','users':'USR','voucher_receipt':'VCH-R',
            'voucher_payment':'VCH-P','journal_entry':'JRN','currencies':'CUR',
            'banks':'BNK','demand_letters':'DL','alerts':'ALR','archive':'ARC'
        };
        const pfx = prefix[type] || (type.toUpperCase().slice(0,3));
        newRec.id = pfx + '-' + Date.now().toString().slice(-5);
        newRec.schoolId = window.currentSchoolId || 1;
        newRec.date = new Date().toISOString().split('T')[0];

        DB[collKey].unshift(newRec);
        toast('🎉 تم حفظ وإضافة السجل الجديد بنجاح!');
    }

    // Direct FastAPI Backend Persistence Sync (SQLite3)
    try {
        fetch('/api/' + type, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newRec)
        }).then(r => r.json()).then(data => {
            console.log('FastAPI Backend Persistence Sync Success:', data);
        }).catch(err => {
            console.log('FastAPI Sync Note (Offline Mode Active):', err);
        });
    } catch(e) {}

    closeModal('formModal');
    if (typeof hydrateAndMountAllGrids === 'function') hydrateAndMountAllGrids();

    window.currentEditingType = null;
    window.currentEditingId = null;
    return true;
}
window.saveForm = saveForm;



function deleteItem(collectionKey, itemId) {
    if (!collectionKey) return;
    if (confirm('❓ هل أنت متأكد من رغبتك في حذف السجل رقم (' + itemId + ') نهائياً؟')) {
        if (DB[collectionKey]) {
            const before = DB[collectionKey].length;
            DB[collectionKey] = DB[collectionKey].filter(x =>
                x.id != itemId && x.keyId != itemId && x.isoCode != itemId &&
                x.provider != itemId && x.name != itemId
            );
            const after = DB[collectionKey].length;
            if (before > after) {
                toast('🗑️ تم حذف السجل (' + itemId + ') بنجاح!');

                // Direct FastAPI Backend Persistence Delete Sync (SQLite3)
                try {
                    fetch('/api/' + collectionKey + '/' + itemId, {
                        method: 'DELETE'
                    }).then(r => r.json()).then(data => {
                        console.log('FastAPI Backend Delete Sync Success:', data);
                    }).catch(err => console.log('FastAPI Delete Note:', err));
                } catch(e) {}
            } else {
                toast('⚠️ لم يتم العثور على السجل', 1);
            }
        }
        if (typeof hydrateAndMountAllGrids === 'function') hydrateAndMountAllGrids();
    }
}
window.deleteItem = deleteItem;


