function renderInteractiveTimetable() {
    const container = document.getElementById('interactiveTimetableMatrix');
    if (!container) return;

    const gradeSelect = document.getElementById('selectGrade') || document.getElementById('ttGradeSelect');
    const sectionSelect = document.getElementById('selectSection') || document.getElementById('ttSectionSelect');

    const grade = gradeSelect ? gradeSelect.value : 'الثالث الثانوي';
    const section = sectionSelect ? sectionSelect.value : 'أ';

    // Attach dynamic change event listeners if not bound
    if (gradeSelect && !gradeSelect.dataset.bound) {
        gradeSelect.dataset.bound = 'true';
        gradeSelect.addEventListener('change', renderInteractiveTimetable);
    }
    if (sectionSelect && !sectionSelect.dataset.bound) {
        sectionSelect.dataset.bound = 'true';
        sectionSelect.addEventListener('change', renderInteractiveTimetable);
    }

    const days = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس'];
    const periods = ['الحصة 1', 'الحصة 2', 'الحصة 3', 'الحصة 4', 'الحصة 5', 'الحصة 6', 'الحصة 7'];

    const mockSchedule = {
        'الأحد': ['الرياضيات', 'الفيزياء', 'استراحة', 'الكيمياء', 'إنجليزي', 'حاسوب', 'رياضة'],
        'الإثنين': ['إنجليزي', 'الرياضيات', 'استراحة', 'عربي', 'تربية إسلامية', 'فيزياء', 'أحياء'],
        'الثلاثاء': ['كيمياء', 'حاسوب', 'استراحة', 'الرياضيات', 'إنجليزي', 'اجتماعيات', 'تفكير نقد'],
        'الأربعاء': ['الفيزياء', 'عربي', 'استراحة', 'الرياضيات', 'كيمياء', 'إنجليزي', 'حاسوب'],
        'الخميس': ['أحياء', 'تربية إسلامية', 'استراحة', 'إنجليزي', 'الرياضيات', 'نشاط حر', 'رياضة']
    };

    let html = `
        <div style="background:rgba(59,130,246,0.2);padding:10px;border-radius:8px;font-weight:800;color:#60a5fa;text-align:center;">اليوم / الحصة</div>
    `;

    periods.forEach(p => {
        html += `<div style="background:rgba(59,130,246,0.15);padding:10px;border-radius:8px;font-weight:800;color:#93c5fd;text-align:center;">${p}</div>`;
    });

    days.forEach(d => {
        html += `<div style="background:rgba(15,23,42,0.9);padding:12px;border-radius:8px;font-weight:700;color:#e2e8f0;display:flex;align-items:center;justify-content:center;">${d}</div>`;
        const daySubjects = mockSchedule[d] || [];
        periods.forEach((p, idx) => {
            const sub = daySubjects[idx] || 'درس أكاديمي';
            const isBreak = sub === 'استراحة';
            html += `
                <div style="background:${isBreak ? 'rgba(107,114,128,0.2)' : 'rgba(30,41,59,0.8)'};border:1px solid ${isBreak ? '#4b5563' : '#334155'};padding:10px;border-radius:8px;text-align:center;cursor:pointer;transition:all 0.2s;" onclick="toast('📌 ${d} - ${p}: مادة (${sub}) للصف ${grade} شعبة ${section}')">
                    <div style="font-weight:700;font-size:0.85rem;color:${isBreak ? '#9ca3af' : '#60a5fa'};">${sub}</div>
                    <div style="font-size:0.75rem;color:var(--muted);margin-top:2px;">${grade} (${section})</div>
                </div>
            `;
        });
    });

    container.innerHTML = html;
}
window.renderInteractiveTimetable = renderInteractiveTimetable;



