function selectChartAccount(code) {
    const acc = ((window.DB && window.DB.accounts) || []).find(a => a.code === code);
    const detailsBody = document.getElementById('chartDetailsBody');
    if (!acc || !detailsBody) return;

    detailsBody.innerHTML = `
        <div style="background:rgba(255,255,255,0.02);padding:14px;border-radius:10px;border:1px solid var(--border);margin-bottom:16px;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
                <h4 style="color:#60a5fa;font-size:1.1rem;font-weight:800;margin:0;">[${acc.code}] ${acc.name}</h4>
                <span style="padding:4px 10px;border-radius:6px;font-size:0.75rem;font-weight:700;background:rgba(16,185,129,0.2);color:#10b981;">نشط 🟢</span>
            </div>
            <div style="font-size:0.85rem;color:var(--muted);margin-bottom:8px;">English Name: ${acc.nameEn || 'N/A'}</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px;font-size:0.85rem;">
                <div><strong>طبيعة الحساب:</strong> <span style="color:#10b981;">${acc.nature}</span></div>
                <div><strong>نوع التدوين:</strong> <span>${acc.postingType}</span></div>
                <div><strong>التصنيف المالي:</strong> <span>${acc.category}</span></div>
                <div><strong>العملة المقررة:</strong> <span>${acc.currency}</span></div>
            </div>
            <div style="margin-top:14px;padding:10px;background:rgba(16,185,129,0.1);border:1px solid rgba(16,185,129,0.3);border-radius:8px;text-align:center;">
                <div style="font-size:0.8rem;color:var(--muted);">الرصيد القائم الحالي:</div>
                <div style="font-size:1.4rem;font-weight:800;color:#34d399;">${Number(acc.balance || 0).toLocaleString()} ${acc.currency}</div>
            </div>
        </div>
    `;
}
window.selectChartAccount = selectChartAccount;


