        { code: 'VOU-2026-005', type: 'سند قيد', date: '2026-08-10', account: '110102 - بنك اليمن والكويت', beneficiary: 'تسوية حسابية بين الحسابات', amount: 200000, currency: 'YER', description: 'قيد تسوية نقدية بين الصندوق والبنك', status: 'ترحيل معتمد 🟢' }
