/* ===== 1. NumPad Auto-Advance Engine (رصد الدرجات السريع) ===== */
function initNumPadAutoAdvance() {
    document.addEventListener('keydown', function(e) {
        if (!e.target.matches('#tbl-interactive-grading input')) return;
        
        const input = e.target;
        const val = parseFloat(input.value);
        const max = parseFloat(input.getAttribute('max') || 100);
        
        // Immediate Validation
        if (val > max) {
            input.style.border = '2px solid #ef4444';
            input.style.background = '#fef2f2';
            toast('⚠️ تنبيه: الدرجة المدخلة تجاوزت الحد الأقصى (' + max + ')');
        } else {
            input.style.border = '';
            input.style.background = '';
        }
        
        // Enter or Down Arrow -> Jump to same column in next row
        if (e.key === 'Enter' || e.key === 'ArrowDown') {
            e.preventDefault();
            const td = input.closest('td');
            const tr = input.closest('tr');
            const colIndex = Array.from(tr.children).indexOf(td);
            const nextTr = tr.nextElementSibling;
            if (nextTr) {
                const nextInput = nextTr.children[colIndex]?.querySelector('input');
                if (nextInput) {
                    nextInput.focus();
                    nextInput.select();
                }
            }
        }
    });
}

/* ===== 2. Privacy Blur / Stealth Mode (وضع التمويه الأمني للكنترول) ===== */
function togglePrivacyBlur() {
    const targets = document.querySelectorAll('#tbl-secret-numbers-grid, #tbl-final-results-grid, #tbl-interactive-grading, #secret_key_display');
    let isBlurred = false;
    targets.forEach(el => {
        el.classList.toggle('privacy-blurred');
        if (el.classList.contains('privacy-blurred')) isBlurred = true;
    });
    
    const icon = document.getElementById('privacyBlurIcon');
    if (icon) {
        icon.className = isBlurred ? 'fa-solid fa-eye' : 'fa-solid fa-eye-slash';
    }
    
    toast(isBlurred ? '🛡️ تم تفعيل وضع التمويه الأمني وإخفاء بيانات الكنترول' : '👁️ تم إلغاء وضع التمويه وإظهار البيانات');
}
window.togglePrivacyBlur = togglePrivacyBlur;

/* ===== 3. Slide-Over Drawer Engine (اللوحة المنزلقة للمعاينة السريعة) ===== */
function openSlideOver(studentId) {
    const container = document.getElementById('slideOverDrawer');
    const body = document.getElementById('slideOverBody');
    const title = document.getElementById('slideOverTitle');
    if (!container || !body) return;
    
    const students = typeof getSchoolData === 'function' ? getSchoolData('students') : (DB.students || []);
    const st = students.find(s => s.id == studentId || s.code == studentId) || students[0] || { name: 'طالب افتراضي', grade: 'الثالث الثانوي', section: 'أ' };
    
    title.innerHTML = `<i class="fa-solid fa-id-card"></i> ملف الطالب: ${st.name}`;
    body.innerHTML = `
        <div style="text-align:center;margin-bottom:20px;padding-bottom:15px;border-bottom:1px solid var(--border-color);">
            <div style="width:80px;height:80px;border-radius:50%;background:#3b82f6;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:2.2rem;margin-bottom:10px;">
                👤
            </div>
            <h3 style="margin:0;">${st.name}</h3>
            <span class="badge badge-info">${st.grade || 'الصف الثالث الثانوي'} (${st.section || 'أ'})</span>
        </div>
        
        <div style="display:grid;gap:12px;font-size:0.95rem;">
            <div><strong>الرقم الأكاديمي:</strong> STU-2026-00${st.id}</div>
            <div><strong>فصيلة الدم:</strong> <span class="badge badge-danger">O+</span></div>
            <div><strong>التنبيه الصحي:</strong> لا توجد حساسيات خيرة</div>
            <div><strong>ولي الأمر:</strong> محمود أحمد العبسي</div>
            <div><strong>هاتف الاتصال:</strong> 📞 771122334</div>
            <div><strong>واتساب الإشعارات:</strong> 💬 771122334</div>
            <div><strong>حق الاستلام القانوني:</strong> الاب (ولاية كاملة 🟢)</div>
            <div><strong>موقع السكن (GPS):</strong> <a href="#" onclick="toast('📍 تم التوجيه لخريطة السكن')" style="color:#60a5fa;">عرض بالخريطة 🗺️</a></div>
        </div>
        
        <h4 style="margin-top:20px;color:var(--primary);border-bottom:1px solid var(--border-color);padding-bottom:8px;">
            <i class="fa-solid fa-file-invoice-dollar"></i> ملخص الموقف المالي
        </h4>
        <div style="background:var(--bg-elevated);padding:12px;border-radius:8px;">
            <div>إجمالي الرسوم: <strong>550,000 YER</strong></div>
            <div>المسدد: <strong style="color:#34d399;">250,000 YER</strong></div>
            <div>المتبقي: <strong style="color:#f87171;">300,000 YER</strong></div>
        </div>
        
        <div style="margin-top:25px;display:flex;gap:10px;">
            <button class="btn-add" style="flex:1;" onclick="toast('✏️ الانتقال لتعديل بيانات الطالب');closeSlideOver();"><i class="fa-solid fa-pen"></i> تعديل البيانات</button>
            <button class="btn-add" style="flex:1;background:#10b981;" onclick="toast('📄 طباعة كشف الحساب');"><i class="fa-solid fa-print"></i> كشف حساب</button>
        </div>
    `;
    
    container.classList.add('active');
}
function closeSlideOver() {
    const container = document.getElementById('slideOverDrawer');
    if (container) container.classList.remove('active');
}
window.openSlideOver = openSlideOver;
window.closeSlideOver = closeSlideOver;

/* ===== 4. Offline Sync Engine (المزامنة والـ Offline) ===== */
function triggerManualSync() {
    const btn = event.currentTarget;
    if (btn) btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جارٍ المزامنة...';
    
    setTimeout(() => {
        const lastSync = document.getElementById('lastSyncTime');
        const pendingCount = document.getElementById('pendingSyncCount');
        if (lastSync) lastSync.innerText = 'الآن (تمت المزامنة بنجاح 🟢)';
        if (pendingCount) pendingCount.innerText = '0 عملية';
        if (btn) btn.innerHTML = '<i class="fa-solid fa-rotate"></i> مزامنة فورية الآن';
        toast('✅ تمت مزامنة جميع البيانات المحفوظة محلياً مع السيرفر الرئيسي بنجاح!');
    }, 1200);
}
window.triggerManualSync = triggerManualSync;

/* ===== 5. Command Palette (ترقية شريط الأوامر Ctrl + K) ===== */
function initCommandPalette() {
    document.addEventListener('keydown', function(e) {
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
            e.preventDefault();
            openCommandPalette();
        }
    });
}

function openCommandPalette() {
    const query = prompt('💡 شريط الأوامر المتقدم (Command Palette):\nأدخل الأمر المطلوبة تنفيذ فوراً:\n1. سند (إنشاء سند قبض/صرف)\n2. طالب (تسجيل طالب جديد)\n3. غياب (رصد الحضور والغياب)\n4. تمويه (وضع التمويه الأمني للكنترول)\n5. مزامنة (مركز المزامنة والـ Offline)');
    if (!query) return;
    const q = query.trim();
    if (q.includes('سند')) { goTo('pg-vouchers'); toast('⚡ تم التوجيه لإدارة السندات'); }
    else if (q.includes('طالب')) { goTo('pg-student-register'); toast('⚡ تم التوجيه لتسجيل طالب جديد'); }
    else if (q.includes('غياب')) { goTo('pg-emp-attendance'); toast('⚡ تم التوجيه لرصد الحضور'); }
    else if (q.includes('تمويه')) { togglePrivacyBlur(); }
    else if (q.includes('مزامنة')) { goTo('pg-sync-center'); toast('⚡ تم التوجيه لمركز المزامنة'); }
    else { toast('💡 تم البحث في النظام عن: ' + q); }
}
window.openCommandPalette = openCommandPalette;

// Auto initialize on load
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
        initNumPadAutoAdvance();
        initCommandPalette();
    });
} else {
    initNumPadAutoAdvance();
    initCommandPalette();
}


/* ===== Universal Engine to Automatically Hide Columns with 'كود' in Title ===== */
function hideCodeColumnsGlobally() {
    try {
        document.querySelectorAll('table').forEach(table => {
            const ths = table.querySelectorAll('thead th');
            const codeColIndices = [];
            
            ths.forEach((th, idx) => {
                const txt = (th.textContent || '').trim();
                if (txt.includes('كود')) {
                    th.style.display = 'none';
                    codeColIndices.push(idx);
                }
            });
            
            if (codeColIndices.length > 0) {
                table.querySelectorAll('tbody tr').forEach(tr => {
                    codeColIndices.forEach(idx => {
                        if (tr.children[idx]) {
                            tr.children[idx].style.display = 'none';
                        }
                    });
                });
            }
        });
    } catch(e) {
        console.warn('hideCodeColumnsGlobally error:', e);
    }
}
window.hideCodeColumnsGlobally = hideCodeColumnsGlobally;

// Auto-hook into page navigation and grid mounting
if (typeof hydrateAndMountAllGrids === 'function') {
    const origHydrate = hydrateAndMountAllGrids;
    hydrateAndMountAllGrids = function() {
        origHydrate.apply(this, arguments);
        setTimeout(hideCodeColumnsGlobally, 50);
        setTimeout(hideCodeColumnsGlobally, 200);
    };
    window.hydrateAndMountAllGrids = hydrateAndMountAllGrids;
}

if (typeof goTo === 'function') {
    const origGoTo = goTo;
    goTo = function(pageId) {
        origGoTo.apply(this, arguments);
        setTimeout(hideCodeColumnsGlobally, 50);
        setTimeout(hideCodeColumnsGlobally, 200);
    };
    window.goTo = goTo;
}

// Auto-run on load and state changes
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hideCodeColumnsGlobally);
} else {
    hideCodeColumnsGlobally();
}
window.addEventListener('load', hideCodeColumnsGlobally);
setInterval(hideCodeColumnsGlobally, 1000);


/* ===== Session Persistence & Restoration Engine ===== */
function saveUserSession(user, token, activePage) {
    try {
        const sessData = {
            user: user || window.me,
            token: token || ('sec_token_' + Date.now()),
            activePage: activePage || window.currentPageId || 'pg-dashboard',
            timestamp: Date.now()
        };
        localStorage.setItem('sec_user_session', JSON.stringify(sessData));
    } catch(e) {}
}
window.saveUserSession = saveUserSession;

function restoreUserSession() {
    try {
        const raw = localStorage.getItem('sec_user_session');
        if (!raw) return false;
        const sess = JSON.parse(raw);
        
        // Expiry check: 24 hours (86400000 ms)
        if (!sess || !sess.user || (Date.now() - sess.timestamp) > 86400000) {
            localStorage.removeItem('sec_user_session');
            return false;
        }
        
        // Restore session variables
        window.me = sess.user;
        window.currentSchoolId = sess.user.schoolId || 1;
        
        // Update user UI elements
        const nameEl = document.getElementById('userName');
        const roleEl = document.getElementById('userRole');
        if (nameEl) nameEl.textContent = sess.user.name || 'مستخدم النظام';
        if (roleEl) roleEl.textContent = sess.user.role || 'مدير المنصة';
        
        // Apply RBAC & hide login modal
        if (typeof applyRBACPermissions === 'function') applyRBACPermissions(sess.user);
        const modal = document.getElementById('loginModal');
        if (modal) modal.style.display = 'none';
        
        // Navigate to active page
        const pageToNav = sess.activePage || (sess.user.role === 'parent' ? 'pg-parent-dashboard' : 'pg-dashboard');
        if (typeof goTo === 'function') goTo(pageToNav);
        
        toast(`👋 مرحباً بك مجدداً ${sess.user.name}! تم استعادة الجلسة بنجاح 🟢`);
        return true;
    } catch(e) {
        console.warn('restoreUserSession error:', e);
        return false;
    }
}
window.restoreUserSession = restoreUserSession;

function clearUserSession() {
    try {
        localStorage.removeItem('sec_user_session');
        sessionStorage.clear();
    } catch(e) {}
}
window.clearUserSession = clearUserSession;

// Save session on login submit
if (typeof handleLoginSubmit === 'function') {
    const origLoginSubmit = handleLoginSubmit;
    handleLoginSubmit = function(e) {
        origLoginSubmit.apply(this, arguments);
        if (window.me) {
            saveUserSession(window.me, null, window.me.role === 'parent' ? 'pg-parent-dashboard' : 'pg-dashboard');
        }
    };
    window.handleLoginSubmit = handleLoginSubmit;
}

// Clear session on logout
if (typeof logout === 'function') {
    const origLogout = logout;
    logout = function() {
        clearUserSession();
        origLogout.apply(this, arguments);
    };
    window.logout = logout;
}

// Auto-run session restore on load
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', restoreUserSession);
} else {
    restoreUserSession();
}


/* ===== ⚡ Central Event-Driven Real-Time Sync Engine (مزامنة تلقائية ولحظية) ===== */
const SystemEventBus = {
    listeners: {},
    on(event, callback) {
        if (!this.listeners[event]) this.listeners[event] = [];
        this.listeners[event].push(callback);
    },
    emit(event, data) {
        console.log(`⚡ [EventBus] Real-Time Sync Event: "${event}"`, data);
        
        // Log event to Audit Trail
        try {
            if (window.DB && window.DB.auditLogs) {
                window.DB.auditLogs.unshift({
                    id: 'AUD-' + Date.now(),
                    date: new Date().toISOString().replace('T', ' ').substring(0, 19),
                    user: (window.me ? window.me.name : 'النظام الآلي'),
                    action: 'مزامنة تلقائية: ' + event,
                    ip: '127.0.0.1 (Local System Bus)',
                    details: JSON.stringify(data || {})
                });
            }
        } catch(e) {}

        // Execute all registered event handlers
        if (this.listeners[event]) {
            this.listeners[event].forEach(cb => {
                try { cb(data); } catch(e) { console.warn(`Event listener error for ${event}:`, e); }
            });
        }
        
        // Auto-refresh active page grids & hide code columns
        setTimeout(() => {
            if (typeof hydrateAndMountAllGrids === 'function') hydrateAndMountAllGrids();
            if (typeof hideCodeColumnsGlobally === 'function') hideCodeColumnsGlobally();
            if (typeof attachRowInteractions === 'function') attachRowInteractions();
        }, 100);
    }
};
window.SystemEventBus = SystemEventBus;

/* ===== Register Event-Driven Sync Handlers across all 6 Sectors ===== */
function initRealTimeSyncHandlers() {

    // ----- Sector 1: Students & Services ↔ Finance & Control -----
    
    // 1. New Student Registered -> Student Account, Academic Tree, Dashboard
    SystemEventBus.on('STUDENT_REGISTERED', function(data) {
        const student = data.student || data;
        
        // A. Add to DB.students if not exists
        if (window.DB && window.DB.students) {
            const exists = window.DB.students.some(s => s.id == student.id);
            if (!exists) window.DB.students.push(student);
        }
        
        // B. Post registration fee voucher & ledger
        if (window.DB && window.DB.receipts) {
            window.DB.receipts.push({
                id: 'REC-2026-' + Math.floor(Math.random()*900+100),
                student: student.name,
                amount: '250,000 YER',
                date: new Date().toISOString().substring(0, 10),
                status: 'مقبوض 🟢',
                notes: 'رسوم تسجيل وحجز مقعد'
            });
        }

        // C. Send SMS Notification
        SystemEventBus.emit('AUTOMATED_SMS_NOTIFICATION', {
            target: student.guardianPhone || '771122334',
            template: 'إشعار قبول وتسجيل طالب',
            msg: `عزيزي ولي الأمر، تم تسجيل الطالب ${student.name} بنجاح بالصف ${student.grade || 'الأول'}.`
        });

        toast(`⚡ مزامنة لحظية: تم تسجيل الطالب ${student.name}، فتح كشف الحساب، وتحديث إحصائيات الداشبورد تلقائياً! 🟢`);
    });

    // 2. Student Discontinued -> Freeze Accounts, Cancel Bus, Remove Seat Numbers
    SystemEventBus.on('STUDENT_DISCONTINUED', function(data) {
        const studentId = data.studentId || data.id;
        
        if (window.DB && window.DB.students) {
            const st = window.DB.students.find(s => s.id == studentId);
            if (st) st.status = 'منقطع / منسحب 🔴';
        }

        // Cancel transport bus seat
        if (window.DB && window.DB.transport) {
            window.DB.transport.forEach(b => {
                if (b.capacity && b.capacity.includes('طالب')) {
                    let cap = parseInt(b.capacity) + 1;
                    b.capacity = cap + ' طالب (تم تحرير مقعد)';
                }
            });
        }

        toast(`⚡ مزامنة لحظية: تم إيقاف مطالبات الطالب، تحرير مقعد الحافلة، واستبعاده من الكنترول! 🟢`);
    });

    // 3. Batch Promotion -> Fee Schedule & Carried Balance
    SystemEventBus.on('STUDENT_PROMOTED', function(data) {
        toast(`⚡ مزامنة لحظية: تم ترفيع الطلاب، ترحيل الأرصدة المتبقية، وتوثيق العام الدراسي الجديد! 🟢`);
    });

    // 4. Transport Enrolled -> Bus Capacity & Ledger Fee
    SystemEventBus.on('TRANSPORT_ENROLLED', function(data) {
        if (window.DB && window.DB.transport) {
            const bus = window.DB.transport[0];
            if (bus) {
                let cap = Math.max(0, parseInt(bus.capacity || 30) - 1);
                bus.capacity = cap + ' طالب (محدث)';
            }
        }
        toast(`⚡ مزامنة لحظية: تم خصم مقعد من الحافلة وإدراج رسوم المواصلات بكشف الحساب! 🟢`);
    });

    // ----- Sector 2: HR & Operations ↔ Timetable & Security -----

    // 1. Employee Attendance Marked -> Schedule Warning & Substitute Teacher Algorithm
    SystemEventBus.on('EMP_ATTENDANCE_MARKED', function(data) {
        if (data && data.status === 'غائب') {
            SystemEventBus.emit('AUTOMATED_SMS_NOTIFICATION', {
                target: '770000000',
                template: 'تنبيه غياب معلم',
                msg: `تنبيه إداري: تم تسجيل غياب المعلم ${data.name || 'المعلم'}. تم تفعيل خوارزمية ترشيح المدرس البديل.`
            });
            toast(`⚠️ مزامنة لحظية: المعلم غائب! تم كشف الحصص وتفعيل خوارزمية ترشيح المدرس البديل! 🟢`);
        }
    });

    // 2. Employee Terminated -> Freeze User Account, Revoke Session, Log Security Audit
    SystemEventBus.on('EMP_TERMINATED', function(data) {
        if (window.DB && window.DB.users) {
            const user = window.DB.users.find(u => u.id == data.empId || u.name == data.name);
            if (user) user.status = 'معطل/غير نشط 🔴';
        }
        toast(`🔒 مزامنة أمان لحظية: تم إنهاء الخدمة، تجميد حساب المستخدم، وإبطال رمز الجلسة فوراً! 🟢`);
    });

    // 3. Monthly Payroll Processed -> Auto Journal, Cashbox Deduction, Advance Repayment
    SystemEventBus.on('PAYROLL_PROCESSED', function(data) {
        const amount = data.amount || 350000;
        
        // Auto Journal Entry
        if (window.DB && window.DB.vouchers) {
            window.DB.vouchers.push({
                id: 'VCH-PAYROLL-' + Date.now(),
                date: new Date().toISOString().substring(0, 10),
                type: 'صرف',
                amount: amount.toLocaleString() + ' YER',
                account: 'حساب رواتب وأجور الموظفين',
                notes: 'مسير الرواتب الشهرية والبدلات',
                status: 'معتمد ومرحل 🟢'
            });
        }
        toast(`⚡ مزامنة لحظية: تم توليد قيد الرواتب الآلي، الخصم من الخزينة، وخصم قسط السلفة! 🟢`);
    });

    // ----- Sector 3: Finance & Accounting ↔ Cashboxes & Dashboard -----

    // 1. Voucher Created -> Cashbox Balance, Auto Journal, Debit/Credit Ledger, Dashboard KPIs
    SystemEventBus.on('VOUCHER_CREATED', function(voucher) {
        const v = voucher.voucher || voucher;
        const amt = parseFloat(String(v.amount).replace(/[^0-9.]/g, '')) || 100000;
        
        // Update Cashbox Balance
        if (window.DB && window.DB.cashboxes) {
            const cb = window.DB.cashboxes[0];
            if (cb) {
                let current = parseFloat(String(cb.currentBalance || 5000000).replace(/[^0-9.]/g, ''));
                if (v.type === 'قبض') current += amt;
                else current -= amt;
                cb.currentBalance = current.toLocaleString() + ' YER';
            }
        }

        // Send Payment Receipt SMS
        if (v.type === 'قبض') {
            SystemEventBus.emit('AUTOMATED_SMS_NOTIFICATION', {
                target: '771122334',
                template: 'إشعار سداد ورصيد',
                msg: `تم استلام مبلغ ${v.amount} بموجب سند قبض رقم ${v.id}. شكراً لالتزامكم.`
            });
        }

        toast(`⚡ مزامنة مالية لحظية: تم تحديث رصيد الصندوق، إنشاء القيد الآلي، وتحديث مؤشرات الداشبورد! 🟢`);
    });

    // ----- Sector 4: Exams & Control ↔ Results & Portals -----

    // 1. Grading Updated -> Auto Calculate GPA, Top Students, Control Reports, Parent Portal
    SystemEventBus.on('GRADING_UPDATED', function(data) {
        // Re-render Parent Portal & Top Students
        if (typeof renderParentGrades === 'function') renderParentGrades();
        toast(`⚡ مزامنة كنترول لحظية: تم احتساب المعدل، تحديث قائمة الأوائل، ونشر النتيجة في بوابة ولي الأمر! 🟢`);
    });

    // 2. Exam Schedule Updated -> Reserve Halls, Freeze Regular Timetable
    SystemEventBus.on('EXAM_SCHEDULED', function(data) {
        toast(`⚡ مزامنة لحظية: تم حجز القاعات واللجان وتجميد جدول الحصص الاعتيادي لفترة الامتحانات! 🟢`);
    });

    // ----- Sector 5: Warehouse & Inventory ↔ Finance & Suppliers -----

    // 1. GRN Supply Order Created -> Inventory Stock Increase, Supplier Balance, Stock Journal
    SystemEventBus.on('GRN_SUPPLY_ORDER_CREATED', function(data) {
        if (window.DB && window.DB.inventory_items) {
            const item = window.DB.inventory_items[0];
            if (item) item.qty = (parseInt(item.qty || 30) + 10) + ' قطعة (مُحدث)';
        }
        toast(`⚡ مزامنة مخزنية لحظية: تم زياده الكميات بالمستودع، إثبات مديونية المورد، وتوليد القيد المحاسبي! 🟢`);
    });

    // 2. GIN Issue Order Created -> Inventory Stock Decrease, Student Charge, Cost Journal
    SystemEventBus.on('GIN_ISSUE_ORDER_CREATED', function(data) {
        if (window.DB && window.DB.inventory_items) {
            const item = window.DB.inventory_items[0];
            if (item) item.qty = Math.max(0, parseInt(item.qty || 30) - 1) + ' قطعة';
        }
        toast(`⚡ مزامنة مخزنية لحظية: تم الخصم الفوري للكتب/الزي من المستودع وتوليد قيد التكلفة! 🟢`);
    });

    // ----- Sector 6: Automated Notifications & Security ↔ All Interfaces -----

    // 1. Automated SMS / WhatsApp Notification Gateway
    SystemEventBus.on('AUTOMATED_SMS_NOTIFICATION', function(sms) {
        if (window.DB && window.DB.whatsapp_send) {
            window.DB.whatsapp_send.unshift({
                id: 'MSG-' + Date.now(),
                target: sms.target || '771122334',
                template: sms.template || 'تنبيه آلي',
                status: 'تم الإرسال والقراءة 🟢',
                cost: '$ 0.005',
                time: new Date().toISOString().replace('T', ' ').substring(0, 19)
            });
        }
        toast(`📱 إشعار واتساب تلقائي: ${sms.msg}`);
    });
}

// Auto Initialize Handlers
initRealTimeSyncHandlers();


