/* ===== 📷 Device Image Upload & Base64 FileReader Engine ===== */
function handleDeviceImageSelect(fileInput, targetInputId) {
    try {
        const file = fileInput.files && fileInput.files[0];
        if (!file) return;
        
        if (!file.type.startsWith('image/')) {
            toast('⚠️ خطأ: يرجى اختيار ملف صورة صالحة (PNG, JPG, WEBP, GIF)', 1);
            return;
        }
        
        if (file.size > 8 * 1024 * 1024) {
            toast('⚠️ تنبيه: حجم الصورة يتجاوز 8 ميجابايت', 1);
        }
        
        const reader = new FileReader();
        reader.onload = function(e) {
            const base64Data = e.target.result;
            const targetInput = document.getElementById(targetInputId);
            if (targetInput) {
                targetInput.value = base64Data;
                targetInput.dispatchEvent(new Event('input', { bubbles: true }));
                targetInput.dispatchEvent(new Event('change', { bubbles: true }));
            }
            
            // Update preview thumbnail
            let previewBox = document.getElementById(targetInputId + '_preview_box');
            let previewImg = document.getElementById(targetInputId + '_preview_img');
            
            if (!previewBox && targetInput) {
                const wrapper = targetInput.closest('.form-group') || targetInput.parentElement;
                if (wrapper) {
                    const div = document.createElement('div');
                    div.id = targetInputId + '_preview_box';
                    div.style.cssText = 'display:flex;align-items:center;gap:10px;margin-top:8px;background:var(--bg-elevated,#0f172a);padding:6px 12px;border-radius:8px;border:1px solid var(--border-color,#334155);';
                    div.innerHTML = `<img id="${targetInputId}_preview_img" src="${base64Data}" style="width:45px;height:45px;border-radius:50%;object-fit:cover;border:2px solid #3b82f6;"><span style="font-size:0.8rem;color:#34d399;font-weight:700;">📷 تم اختيار الصورة من الجهاز بنجاح!</span>`;
                    wrapper.appendChild(div);
                }
            } else {
                if (previewImg) previewImg.src = base64Data;
                if (previewBox) previewBox.style.display = 'flex';
            }
            
            toast('📷 تم تحميل واختيار الصورة من جهازك بنجاح 🟢');
        };
        reader.readAsDataURL(file);
    } catch(err) {
        console.warn('handleDeviceImageSelect error:', err);
    }
}
window.handleDeviceImageSelect = handleDeviceImageSelect;

/* ===== Automatic Enhancement of all Image & Photo Inputs ===== */
function enhanceAllImageFieldsGlobally() {
    try {
        const inputs = document.querySelectorAll('input[type="text"], input[type="url"]');
        inputs.forEach(input => {
            const id = input.id || '';
            const placeholder = input.placeholder || '';
            const labelText = input.previousElementSibling ? input.previousElementSibling.textContent : '';
            
            const isImageField = /avatar|photo|logo|image|picture|صورة|شعار/i.test(id + ' ' + placeholder + ' ' + labelText);
            
            if (isImageField && !input.dataset.uploadEnhanced) {
                input.dataset.uploadEnhanced = 'true';
                
                // Wrap in input group with file picker button
                const parent = input.parentElement;
                if (!parent || parent.classList.contains('image-upload-enhanced')) return;
                
                const wrapper = document.createElement('div');
                wrapper.className = 'image-upload-enhanced';
                wrapper.style.cssText = 'display:flex;gap:8px;align-items:center;width:100%;margin-top:4px;';
                
                input.parentNode.insertBefore(wrapper, input);
                wrapper.appendChild(input);
                input.style.flex = '1';
                
                const labelBtn = document.createElement('label');
                labelBtn.className = 'btn-add';
                labelBtn.style.cssText = 'margin:0;padding:8px 12px;font-size:0.82rem;cursor:pointer;white-space:nowrap;background:linear-gradient(135deg,#3b82f6,#2563eb);color:#fff;border-radius:8px;display:inline-flex;align-items:center;gap:6px;box-shadow:0 2px 6px rgba(59,130,246,0.3);';
                labelBtn.innerHTML = `<i class="fa-solid fa-folder-open"></i> رفع من الجهاز <input type="file" accept="image/*" style="display:none;" onchange="handleDeviceImageSelect(this, '${id}')">`;
                
                wrapper.appendChild(labelBtn);
            }
        });
    } catch(e) {
        console.warn('enhanceAllImageFieldsGlobally error:', e);
    }
}
window.enhanceAllImageFieldsGlobally = enhanceAllImageFieldsGlobally;

// Auto-run enhancement on form modals & page changes
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
        enhanceAllImageFieldsGlobally();
        setInterval(enhanceAllImageFieldsGlobally, 1000);
    });
} else {
    enhanceAllImageFieldsGlobally();
    setInterval(enhanceAllImageFieldsGlobally, 1000);
}


