// 28. Toggle Grading Lock
function toggleGradingLock() {
    const isLocked = confirm('هل تريد تبديل حالة قفل شيت رصد الدرجات لمنع التعديل؟');
    if (isLocked) {
        toast('🔒 تم قفل شيت الرصد بنجاح، لا يمكن تعديل الدرجات إلا بطلب فك قفل معتمد.');
    } else {
        toast('🔓 شيت الرصد مفتوح للتعديل.');
    }
}
window.toggleGradingLock = toggleGradingLock;

// 29. Toggle Password Visibility
function togglePasswordVisibility(inputId) {
    const el = document.getElementById(inputId) || document.querySelector('input[type="password"]');
    if (el) {
        el.type = (el.type === 'password') ? 'text' : 'password';
    }
}
window.togglePasswordVisibility = togglePasswordVisibility;

