function renderAiPredictiveAnalytics() {
    const el = document.getElementById('tbl-predictive-students');
    if (!el) return;

    const q = (document.getElementById('searchAiPredictive')?.value || '').toLowerCase();
    const riskFilter = document.getElementById('filterAiRiskLevel')?.value || 'ALL';
    const gradeFilter = document.getElementById('filterAiGrade')?.value || 'ALL';

    const filtered = AI_PREDICTIVE_DATA.filter(item => {
        const matchesQ = !q || item.name.toLowerCase().includes(q) || item.academicNo.toLowerCase().includes(q) || item.grade.toLowerCase().includes(q);
        const matchesRisk = (riskFilter === 'ALL') || (item.riskLevel === riskFilter);
        const matchesGrade = (gradeFilter === 'ALL') || (item.grade.includes(gradeFilter));
        return matchesQ && matchesRisk && matchesGrade;
    });

    // Update KPI counts
    const dHigh = document.getElementById('aiCountHighRisk');
    const dMed = document.getElementById('aiCountMedRisk');
    const dSafe = document.getElementById('aiCountSafe');
    if (dHigh) dHigh.textContent = AI_PREDICTIVE_DATA.filter(x => x.riskLevel === 'HIGH').length;
    if (dMed) dMed.textContent = AI_PREDICTIVE_DATA.filter(x => x.riskLevel === 'MEDIUM').length;
    if (dSafe) dSafe.textContent = 810 + AI_PREDICTIVE_DATA.filter(x => x.riskLevel === 'LOW').length;

    el.innerHTML = filtered.map((item, i) => {
        let badgeClass = 'low';
        let badgeText = 'مستقر وآمن 🟢';
        let barClass = 'low';
        if (item.riskLevel === 'HIGH') {
            badgeClass = 'high';
            badgeText = `خطر حرج (${item.riskScore}%) 🔴`;
            barClass = 'high';
        } else if (item.riskLevel === 'MEDIUM') {
            badgeClass = 'medium';
            badgeText = `إنذار مبكر (${item.riskScore}%) 🟡`;
            barClass = 'medium';
        }

        const driversHtml = item.drivers.map(d => `<div style="font-size:0.78rem;color:#cbd5e1;display:flex;align-items:center;gap:4px;"><i class="fa-solid fa-angle-left" style="color:#8b5cf6;font-size:0.7rem;"></i> ${d}</div>`).join('');

        return `<tr>
            <td>${i + 1}</td>
            <td>
                <div style="font-weight:700;color:#60a5fa;">${item.name}</div>
                <div style="font-family:monospace;font-size:0.75rem;color:#94a3b8;">${item.academicNo}</div>
            </td>
            <td><span class="badge badge-info">${item.grade} - ${item.section}</span></td>
            <td style="min-width:140px;">
                <span class="risk-badge ${badgeClass}">${badgeText}</span>
                <div class="risk-meter">
                    <div class="risk-meter-fill ${barClass}" style="width:${item.riskScore}%;"></div>
                </div>
            </td>
            <td>${driversHtml}</td>
            <td style="font-size:0.82rem;color:#fca5a5;font-weight:600;">${item.forecast}</td>
            <td style="font-size:0.8rem;color:#e2e8f0;max-width:200px;">
                <div style="font-weight:600;color:#c084fc;margin-bottom:2px;"><i class="fa-solid fa-clipboard-check"></i> ${item.remedialPlan}</div>
                <div style="font-size:0.72rem;color:#94a3b8;">الحالة: ${item.planStatus}</div>
            </td>
            <td style="white-space:nowrap;">
                <button class="btn-sm" style="background:#3b82f6;color:#fff;border:none;padding:5px 9px;border-radius:6px;cursor:pointer;margin-bottom:3px;" onclick="assignRemedialPlan('${item.id}')" title="تطبيق وتعديل الخطة العلاجية">
                    <i class="fa-solid fa-hand-holding-medical"></i> الخطة العلاجية
                </button>
                <button class="btn-sm" style="background:#10b981;color:#fff;border:none;padding:5px 9px;border-radius:6px;cursor:pointer;" onclick="sendGentleParentNotification('${item.id}')" title="إرسال إشعار لطيف لولي الأمر عبر الواتساب والتطبيق">
                    <i class="fa-brands fa-whatsapp"></i> إشعار ولي الأمر
                </button>
            </td>
        </tr>`;
    }).join('') || '<tr><td colspan="8" style="text-align:center;padding:24px;color:#94a3b8;">لا توجد حالات مطابقة لمعايير البحث المحددة</td></tr>';
}
