// Send Gentle Parent Notification
function sendGentleParentNotification(studentId) {
    const student = AI_PREDICTIVE_DATA.find(s => s.id === studentId) || AI_PREDICTIVE_DATA[0];
    const gentleMessage = `عزيزي ولي أمر الطالب/ة (${student.name}) المحترم،\n\nتحية طيبة من إدارة مدرسة السحاب النموذجية،\n\nفي إطار حرصنا المشترك على تميز وتفوق أبنائنا ومتابعتهم المستمرة، نود إحاطتكم بأن فريق التوجيه الأكاديمي قد أعد خطة متابعة ودعم تعليمي مخصصة للطالب لتعزيز مستواه في (${student.academicDrop.replace('-', '')}) واستثمار طاقاته بأفضل شكل.\n\nنثمن تعاونكم المستمر معنا، ويسرنا تواصلكم مع المرشد الأكاديمي للاطلاع على تفاصيل خطة الدعم.\n\nدمتم ودام أبناؤنا في تميز ونجاح. 🌟`;
    
    alert(`📱 معاينة الإشعار التربوي اللطيف المرسل لولي الأمر عبر التطبيق و WhatsApp:\n\n${gentleMessage.replace(/\\n/g, '\n')}`);
    toast(`✅ تم إرسال الإشعار التربوي اللطيف لولي أمر الطالب (${student.name}) بنجاح!`);
}
window.sendGentleParentNotification = sendGentleParentNotification;

// Assign Remedial Plan
function assignRemedialPlan(studentId) {
    const student = AI_PREDICTIVE_DATA.find(s => s.id === studentId) || AI_PREDICTIVE_DATA[0];
    const newPlan = prompt(`تحديث الخطة العلاجية والتدخل الأكاديمي للطالب (${student.name}):`, student.remedialPlan);
    if (newPlan) {
        student.remedialPlan = newPlan;
        student.planStatus = 'تم اعتماد الخطة والبدء بها 🟢';
        renderAiPredictiveAnalytics();
        toast('✅ تم اعتماد الخطة العلاجية وإشعار المشرف الأكاديمي ومعلم المادة بنجاح!');
    }
}
window.assignRemedialPlan = assignRemedialPlan;

